        List<Ruling> horizontals = new ArrayList<>();
        horizontals.add(h1);
        horizontals.add(h2);

        // Setup Vertical Rulings
        // V1: x=50, y from 50 to 250 (intersects both H1 and H2)
        Ruling v1 = new Ruling(50.0f, 50.0f, 0.0f, 200.0f);
        // V2: x=80, y from 50 to 250 (intersects both H1 and H2)
        Ruling v2 = new Ruling(50.0f, 80.0f, 0.0f, 200.0f);
        
        List<Ruling> verticals = new ArrayList<>();
        verticals.add(v1);
        verticals.add(v2);

        // Execute: Find intersections
        Map<Point2D, Ruling[]> result = Ruling.findIntersections(horizontals, verticals);

        // Assert: We expect a 2x2 grid, so 4 intersection points
        Assert.assertNotNull(result);
        Assert.assertEquals("Should find 4 intersection points", 4, result.size());

        // Define expected intersection points
        Point2D p1 = new Point2D.Float(50.0f, 100.0f); // V1 intersects H1
        Point2D p2 = new Point2D.Float(80.0f, 100.0f); // V2 intersects H1
        Point2D p3 = new Point2D.Float(50.0f, 200.0f); // V1 intersects H2
        Point2D p4 = new Point2D.Float(80.0f, 200.0f); // V2 intersects H2

        // Assert presence of points
        Assert.assertTrue("Map should contain (50, 100)", result.containsKey(p1));
        Assert.assertTrue("Map should contain (80, 100)", result.containsKey(p2));
        Assert.assertTrue("Map should contain (50, 200)", result.containsKey(p3));
        Assert.assertTrue("Map should contain (80, 200)", result.containsKey(p4));

        // Assert structure of value (Ruling array) for one intersection
        Ruling[] intersectingRulings = result.get(p1);
        Assert.assertEquals("Should return pair of rulings", 2, intersectingRulings.length);
        
        // Based on method logic: 
        // index 0 is from the horizontal list (tree), index 1 is from the vertical list (so.ruling)
        Ruling resH = intersectingRulings[0];
        Ruling resV = intersectingRulings[1];

